ref_dict.thm:approximate_brouwer_turan:
\begin{theorem}\label{thm:approximate_brouwer_turan}
  Let $r\ge 2$. Let $G=(V,E)$ be a $K_{r+1}$-free graph, and let $1\le k\le |V|$. Then,
\[
    \eps_k(G) \le \left(1-\frac{1}{r}\right)\frac{k^2}{2}+ (4k-2)\sqrt{k}.
\]  
\end{theorem}

ref_dict.thm:main_token:
\begin{theorem}\label{thm:main_token}
 Let $G=(V,E)$ be a graph and let $1\le k\le |V|/2$. Then,\[    \lambda_1(L(F_k(G)))\le |E|+4k-2.\]  
 Moreover, if $G$ is bipartite, then $ \lambda_1(L(F_k(G)))\le |E|+2k-1$.
\end{theorem}

ref_dict.conj:token:
\begin{conjecture}[Apte, Parekh, Sud {\cite{apte2025conjectured}}]\label{conj:token}
Let $G=(V,E)$ be a graph and let $1\le k\le |V|/2$. Then,
\[
    \lambda_1(L(F_k(G)))\le |E|+k.
\]
\end{conjecture}

ref_dict.thm:main_density_version:
\begin{theorem}\label{thm:main_density_version}
Let $G=(V,E)$ be a graph, and let $1\le k\le |V|$. Then,
\[
    \eps_k(G) \le \max_{U\subset V,\, |U|=k} |E_G(U)| + (4k-2)\sqrt{k}.
\]
\end{theorem}

ref_dict.thm:main_brouwer:
\begin{theorem}\label{thm:main_brouwer}
Let $G=(V,E)$ be a graph, and let $1\le k\le |V|$. Then,
\[
    \eps_k(G) \le \binom{k}{2}+ (4k-2)\sqrt{k}.
\]
\end{theorem}

