ref_dict.app:bounds-for-K4:
\begin{proof}
  Similar to in Lemma~\ref{lemma:log-m-signs} we give a proof for
  \(\imag z \leq 0\), with the case \(\imag z > 0\) following in a
  similar way.

  From the proof of Lemma~\ref{lemma:log-m-signs} we have that the
  argument of \(\log^m(1 - tz)\) lies in the interval
  \([m\pi - m\theta, m\pi]\). For the second factor we note that
  \(\imag z \leq 0\) means that the argument of \(1 - tz\) lies in the
  interval \([0, \pi]\), hence the argument of \((1 - tz)^{-2\nu}\)
  lies in \([-2\nu\pi, 0]\). It follows that
  \begin{equation*}
    \arg(\log^{m}(1 - tz)(1 - tz)^{-2\nu}) \in [m\pi - m\theta - 2\nu\pi, m\pi],
  \end{equation*}
  and for this to lie in a single quadrant we must have
  \(m\theta + 2\nu\pi \leq \frac{\pi}{2}\). Since
  \(\nu \in [0, 1 / N_{0}]\), the result follows.
\end{proof}

\subsubsection{Bounding remainder terms using Taylor models}
\label{sec:taylor-models-remainders}
With an implementation of Taylor models for \(F_{N}\) it is relatively
straightforward to compute enclosures of the required remainder terms.
They are all given by the remainder term of a Taylor model of the
associated function.

The function \(T_{6}(N, z)\) is given in Equation~\eqref{eq:T_246}.
Consider a degree 5 Taylor model \(M_{z} = (p_{z}, \Delta_{z})\) of
the function
\begin{equation*}
  \frac{\sqrt{\lambda_{app}}}{\sqrt{\lambda}} c_N |F_N(z)|
\end{equation*}
in the variable \(\nu = N^{-1}\) that is valid on the interval
\([0, 1 / N_{0}]\). By definition of \(\Delta_{z}\) we then have
\begin{equation*}
  T_{6}(N, z) \in \Delta_{z}
\end{equation*}
for any \(\nu \in [0, 1 / N_{0}]\). For \(K_{4}(N, z, t)\) the approach
is similar, in this case it is enclosed by the remainder term of a
degree 3 Taylor model for
\begin{equation*}
  K(z, t) = J_0 \left(\rho^{1/2} |z|^{1/N} \sqrt{F_N(\bar{z}) \left( F_N(z) - (t/z)^{1/N} F_N(t) \right)}\right) \, ,
\end{equation*}
given in Equation~\eqref{eq:definition-of-K(z,t)}. Using that
\(J_{0}(z) = {}_0\tilde{F}_1(1; -z^{2} / 4)\) we can write this as
\begin{equation*}
  K(z, t) = {}_0\tilde{F}_1\left(1; -\frac{1}{4}\rho |z|^{2/N} \left(F_N(\bar{z}) \left( F_N(z) - (t/z)^{1/N} F_N(t) \right)\right)\right) \, .
\end{equation*}
To bound \(C_{F_{N},4}\) in
Lemma~\ref{lemma:K4-bounds-preliminary-constants} we need to compute
a degree 3 Taylor model of
\begin{equation*}
  \frac{\rho^{1/2}}{\lambda^{1/2}}F_N(t).
\end{equation*}

In all cases we compute Taylor models of \(F_{N}\) using the approach
discussed in the above subsection. For the rest, Taylor models can be
computed automatically using Taylor arithmetic and composition of
Taylor models. In a couple of cases we initially compute higher degree
Taylor models which are then truncated to the appropriate degree, this
generally improves the quality of the enclosure of the remainder term.

\section{Bounds for $K_4(N,z,t)$}
\label{app:bounds-for-K4}

This section is devoted to computing bounds on the residue function
\begin{equation*}
  K_4(N,z,t) = \left(K(z,t) - d_0(z,t) - \frac{d_1(z,t)}{N} -
  \frac{d_2(z,t)}{N^2} - \frac{d_3(z,t)}{N^3}\right)N^{4}
\end{equation*}
from
Lemma~\ref{lemma:exact-expression-for-K-up-to-order_-3}
that are valid for \(t\) close to zero.

We first begin by establishing bounds on some functions that will
appear later.
\begin{lemma}
  \label{lemma:K4-bounds-preliminary-constants}
  Let \(N \geq N_{0} = \codenumber{64}\). We have the enclosure
  \begin{equation}\label{eq:rho-lambda-enclosure}
    0 \leq 1 - \frac{\rho^{1/2}}{\lambda^{1/2}} \leq \frac{C_{\rho,\lambda}}{N^5},
  \end{equation}
  for
  \begin{equation*}
    C_{\rho,\lambda} = \codenumber{7}.
  \end{equation*}
  For \(|t| \leq 1\) we have the bounds
  \begin{equation*}
    |S_2(t)| \leq C_{S_2},\quad
    |S_3(t)| \leq C_{S_3}
  \end{equation*}
  with
  \begin{equation*}
    C_{S_{2}} = \codenumber{3.3},\quad
    C_{S_{3}} = \codenumber{2.5}.
  \end{equation*}
  Moreover, we have the bounds
  \begin{align*}
    \left|\frac{\rho^{1/2}}{\lambda^{1/2}}F_N(t)\right| &\leq C_{F_N,0},\\
    \left|\frac{\rho^{1/2}}{\lambda^{1/2}}F_N(t) - 1\right| &\leq \frac{C_{F_N,2}}{N^2},\\
    \left| \frac{\rho^{1/2}}{\lambda^{1/2}} \left(F_N(t) - \frac{S_2(t)}{N^2}\right) - 1 \right| &\leq \frac{C_{F_N,3}}{N^3},\\
    \left| \frac{\rho^{1/2}}{\lambda^{1/2}} \left(F_N(t) - \frac{S_2(t)}{N^2} - \frac{S_3(t)}{N^3} \right) - 1 \right| &\leq \frac{C_{F_N,4}}{N^4}
  \end{align*}
  with
  \begin{equation*}
    C_{F_{N},0} = \codenumber{1.001},\quad
    C_{F_{N},2} = \codenumber{3.5},\quad
    C_{F_{N},3} = \codenumber{3},\quad
    C_{F_{N},4} = \codenumber{11}.
  \end{equation*}
  Finally, we have the bound
  \begin{equation*}
    \|J_{0}^{(8)}\|_{L^{\infty}([0, \infty))} \leq C_{J_{0},8}
  \end{equation*}
  with \(C_{J_{0},8} = \codenumber{0.2734376}\).
\end{lemma}

\begin{proof}
  Let us start with the bound involving \(C_{\rho,\lambda}\).
  Recall that \(\rho = \rho(N) = c_{N}^{2}\lambda_{app}(N)\). Let us
  denote \(\nu = N^{-1}\), we are then interested in controlling
  \(\rho(1 / \nu)\) for \(\nu \in [0, 1 / N_{0}]\). By construction,
  \(\lambda_{app}\) is taken such that for the Taylor expansion at
  \(\nu = 0\), all terms up to \(\nu^{4}\) in
  \begin{equation*}
    1 - \frac{\rho(1 / \nu)^{1/2}}{\lambda^{1/2}}
  \end{equation*}
  vanish. To control \(1 - \frac{\rho(1 / \nu)^{1/2}}{\lambda^{1/2}}\),
  it therefore suffices to compute an enclosure of the fifth term in
  the Taylor expansion that is valid for \(\nu \in [0, 1 / N_{0}]\).
  More precisely we have for \(\nu \in [0, 1 / N_{0}]\) that
  \begin{equation*}
    1 - \frac{\rho(1 / \nu)^{1/2}}{\lambda^{1/2}} = \frac{1}{5!}\frac{d^{5}}{d\nu^{5}}\left(1 - \frac{\rho(1 / \nu)^{1/2}}{\lambda^{1/2}}\right)\Big|_{\nu = \xi}\nu^{5},
  \end{equation*}
  for some \(\xi \in [0, 1 / N_{0}]\). We enclose the derivative on
  the interval \([0, 1 / N_{0}]\) using the approach from
  \eqref{eq:taylor-bound} combined with automatic Taylor
  expansions, giving
  \begin{equation*}
    \frac{1}{5!}\frac{d^{5}}{d\nu^{5}}\left(1 - \frac{\rho(1 / \nu)^{1/2}}{\lambda^{1/2}}\right) \in \resultnumber{[6 \pm 0.633]}.
  \end{equation*}
  Since the enclosure is positive we get that
  \(1 - \frac{\rho^{1/2}}{\lambda^{1/2}}\) is lower bounded by zero.
  Since it is upper bounded by \(C_{\rho,\lambda}\) we get that
  \begin{equation*}
    1 - \frac{\rho^{1/2}}{\lambda^{1/2}} \leq C_{\rho,\lambda}\nu^{5} = \frac{C_{\rho,\lambda}}{N^{5}}.
  \end{equation*}

  Next we look at the bounds for \(S_{2}(t)\) and \(S_{3}(t)\). Since
  both of these functions are analytic on the unit disk it suffices to
  bound the modulus on the boundary of the disk. Moreover, they are
  conjugate symmetric and it hence suffices to bound them for
  \(t = e^{i\theta}\) with \(\theta \in [0, \pi]\). We make use of the
  algorithm discussed in Appendix~\ref{sec:enclosing-extrema} for
  enclosing the maximum on this interval. The procedure to compute
  enclosures of \(S_{2}\) and \(S_{3}\) is discussed in
  Appendix~\ref{sec:polylogs}. From this we get the enclosures
  \begin{equation*}
    \max_{\theta \in [0, \pi]} |S_{2}(e^{i\theta})| \in \resultnumber{[3.29 \pm 1.28 \cdot 10^{-3}]},\quad
    \max_{\theta \in [0, \pi]} |S_{3}(e^{i\theta})| \in \resultnumber{[2.44 \pm 1.98 \cdot 10^{-3}]},
  \end{equation*}
  which implies the proposed bounds.

  For the bounds related to \(F_{N}\) we start by noting that it
  suffices to prove the bound with \(C_{F_{N},4}\), the other bounds
  then follow from
  \begin{align*}
    \left|\frac{\rho^{1/2}}{\lambda^{1/2}}F_N(t)\right|
    &\leq 1 + \left|\frac{\rho^{1/2}}{\lambda^{1/2}}\frac{S_2(t)}{N^3}\right| + \left|\frac{\rho^{1/2}}{\lambda^{1/2}}\frac{S_3(t)}{N^3}\right| + \frac{C_{F_N,4}}{N^4}
      \leq 1 + \frac{C_{S_{2}}}{N_{0}^{2}} + \frac{C_{S_{3}}}{N_{0}^{3}} + \frac{C_{F_N,4}}{N_{0}^{4}}
      \leq C_{F_{N},0},\\
    \left|\frac{\rho^{1/2}}{\lambda^{1/2}}F_N(t) - 1\right|
    &\leq \left|\frac{\rho^{1/2}}{\lambda^{1/2}}\frac{S_2(t)}{N^3}\right| + \left|\frac{\rho^{1/2}}{\lambda^{1/2}}\frac{S_3(t)}{N^3}\right| + \frac{C_{F_N,4}}{N^4}
      \leq \left(C_{S_{2}} + \frac{C_{S_{3}}}{N_{0}} + \frac{C_{F_N,4}}{N_{0}^{2}}\right)\frac{1}{N^{2}}
      \leq \frac{C_{F_{N},2}}{N^{2}},\\
    \left| \frac{\rho^{1/2}}{\lambda^{1/2}} \left(F_N(t) - \frac{S_2(t)}{N^2} \right) - 1 \right|
    & \leq \left|\frac{\rho^{1/2}}{\lambda^{1/2}}\frac{S_3(t)}{N^3}\right| + \frac{C_{F_N,4}}{N^4}
      \leq \left(C_{S_{3}} + \frac{C_{F_N,4}}{N_{0}}\right)\frac{1}{N^{3}}
      \leq \frac{C_{F_{N},3}}{N^{3}}.
  \end{align*}
  Where we have used the bound
  \(\left|\frac{\rho^{1/2}}{\lambda^{1/2}}\right| \leq 1\), which
  follows from~\eqref{eq:rho-lambda-enclosure}.

  We next move to establishing the bound with \(C_{F_{N},4}\). Similar
  to for \(S_{2}\) and \(S_{3}\) we start by noticing that
  \begin{equation}\label{eq:scaled-F_N-remainder}
    \frac{\rho^{1/2}}{\lambda^{1/2}} \left(F_N(t) - \frac{S_2(t)}{N^2} - \frac{S_3(t)}{N^3} \right) - 1
  \end{equation}
  is analytic and conjugate symmetric. It hence suffices to bound it
  for \(t = e^{i\theta}\) with \(\theta \in [0, \pi]\). We make use of
  the algorithm discussed in Appendix~\ref{sec:enclosing-extrema} for
  enclosing the maximum on this interval. To evaluate the function we
  make use of Taylor models. Taylor models are discussed in
  Appendix~\ref{sec:taylor-models}, which also contains more details
  about how to compute the function in question using them. This gives
  us the enclosure
  \begin{equation*}
    \max_{\theta \in [0, \pi]} \left|\frac{\rho^{1/2}}{\lambda^{1/2}} \left(F_N(t) - \frac{S_2(t)}{N^2} - \frac{S_3(t)}{N^3} \right) - 1\right|
    \in \resultnumber{[10 \pm 0.298]},
  \end{equation*}
  which implies the required bound.

  Finally, what remains is establishing the bound for \(J_{0}^{(8)}\).
  We start by noticing that the derivative can be explicitly computed
  to be
  \begin{equation*}
    J_{0}^{(8)}(x) = \frac{35J_{0}(x) - 56J_{2}(x) + 28J_{4}(x) - 8J_{6}(x) + J_{8}(x)}{128}.
  \end{equation*}
  To bound it on \([0, \infty)\) we split the interval into
  \([0, 50]\) and \((50, \infty)\). For \(x \in [0, 50]\) we make use
  of the algorithm discussed in Appendix~\ref{sec:enclosing-extrema}
  for enclosing the maximum, giving us:
  \begin{equation*}
    \max_{x \in [0, 50]} |J_{0}^{(8)}| \in \resultnumber{[0.2734375000 \pm 1.75 \cdot 10^{-11}]} < C_{J_{0},8}.
  \end{equation*}
  For \(x \in (50, \infty)\) we use the bound
  \begin{equation*}
    |J_{\nu}(x)| \leq 0.7858 x^{-1 / 3},
  \end{equation*}
  from~\cite{fungrim-7f3485}, giving
  \begin{equation*}
    |J_{0}^{(8)}(x)| \leq 0.7858x^{-1 / 3}
    \leq 0.7858 \cdot 50^{-1 / 3}
    = 0.213298... < C_{J_{0},8}.
  \end{equation*}
\end{proof}

