\section{The Three Dimension Keller-Segel-Stokes Systems}\label{S4}
In this section, we consider the case $N = 3$ and assume that $S$ satisfies condition~\eqref{S} with $\alpha > \frac{1}{3}$. We begin by establishing some a priori estimates in the next subsection. Subsequently, we derive the cornerstone of our analysis, namely the $L^p$ estimate for $n$, and conclude with the proof of Theorem~\ref{thm2} in Subsection~\ref{S4-2}.

\subsection{A Priori Estimates} \label{S4-1}
By combining the Stokes semigroup estimates with the time-uniform boundedness of $n \nabla \phi$, we obtain the following $L^{p}$-estimate for $u$. As the argument is standard and can be found, for example, in \cite{YZ2016}, Lemma~2.5, and \cite{Winkler-2018}, Lemma~2.3, we omit the detailed proof here to avoid redundancy.

\begin{lemma} \label{L2}
    For any $p \in (1,3)$, there exists $C>0$ such that 
    \begin{align}
        \left \|u(\cdot,t) \right \|_{L^p(\Omega)} \leq C\qquad \text{for all }t\in (0,T_{\rm max}).
    \end{align}
\end{lemma}
In preparation for the proof of Lemma~\ref{L5}, we first establish the following lemma, which provides an $L^p$ bound for $c$ with $p < 3$.

\begin{lemma} \label{L3}
        For any $p \in (1,3)$, there exists $C>0$ such that 
    \begin{align}
        \left \|c(\cdot,t) \right \|_{L^p(\Omega)} \leq C\qquad \text{for all }t\in (0,T_{\rm max}).
    \end{align}
\end{lemma}
\begin{proof}
    Multiplying the second equation of \eqref{1} by $(c+1)^{\frac{p}{3}-1}$ and integrating by parts yields
    \begin{align*}
        \left (1 -\frac{p}{3} \right ) \int_\Omega (c+1)^{\frac{p}{3}-2} |\nabla c|^2 &= \int_\Omega c(c+1)^{\frac{p}{3}-1} - \int_\Omega n (c+1)^{\frac{p}{3}-1} \notag  \\
        &\leq \int_\Omega c\qquad \text{for all }t\in (0,T_{\rm max}).
    \end{align*}
    This, together with Lemma \ref{Local}[\eqref{Local.2}] implies that 
    \begin{align*}
        \int_\Omega |\nabla (c+1)^\frac{p}{6}|^2 \leq c_1 \qquad \text{for all }t\in (0,T_{\rm max}) ,
    \end{align*}
    for some $c_1>0$. Applying Sobolev's inequality and Lemma \ref{Local}[\eqref{Local.2}], we can find $c_2>0$ and $c_3>0$ such that
    \begin{align*}
        \int_\Omega (c+1)^p &\leq  c_2 \left (  \int_\Omega |\nabla (c+1)^\frac{p}{6}|^2 \right )^{3} + c_2\left (\int_\Omega (c+1) \right )^p \notag \\
        &\leq c_3  \qquad \text{for all }t\in (0,T_{\rm max}),
    \end{align*}
    which completes the proof.
\end{proof}

