[G\"{u}nt\"{u}rk and Thao]
  \begingroup
  \def\@currentlabelname{}  \ifx\current@theorem\relax\else
    \def\@currentlabelname{\current@theorem}
  \ifx\cref@currentlabel\undefined\else
    \let\@currentlabelname\cref@currentlabel

  \orig@label{f:GT}  \endgroup

Let $\mathcal{L}$ be innately regular, $\lambda\in\left]0,1\right]$, and $x^{(0)}\in X$.
Generate a sequence $(x^{(n)})_{\nnn}$ in $X$ as follows:
Given $x^{(n)}$, pick $R_n \in \mathcal{R}_{\mathcal{L},[\lambda,2-\lambda]}$, and update via
\begin{equation}
  \begingroup
  \def\@currentlabelname{}  \ifx\current@theorem\relax\else
    \def\@currentlabelname{\current@theorem}
  \ifx\cref@currentlabel\undefined\else
    \let\@currentlabelname\cref@currentlabel

  \orig@label{260102a}  \endgroup

  x^{(n+1)} := R_n x^{(n)}.
\end{equation}
Then 
\begin{equation}
\sum_{n=0}^\infty \norm{x^{(n+1)}-x^{(n)}}^\gamma <+\infty\quad \text{for all $\gamma>0$.}
\end{equation}

ref_dict.e:cone:
\begin{example}[G\"unt\"urk-Thao fails for a plane 
and a non-polyhedral cone in $\RR^3$]
\label{e:cone}
    Let $\beta\in \mathbb{R}_{++}$ and $r\in\{2,4,6,\ldots\}$. 
    Consider the function $f(x)=\exp(-\beta x^{-r})$ with domain $\bigl[-\left(\beta r/(r+1)\right)^{1/r},\left(\beta r/(r+1)\right)^{1/r}\bigr]$. Note that $f$ is supercoercive and hence, the assumption of \cref{p:R3sequence2} is satisfied with $q=-r-1$, $\alpha=2\beta$, $p=r$, and $c_{q,\alpha,p}=r\beta$. Hence, we obtain
    \begin{equation}
        1=\lim_{n\to\infty}\frac{b_n}{\left(\frac{\alpha}{\ln(n)}\right)^{1/p}}=\lim_{n\to\infty}\frac{b_n}{\left(\frac{2\beta}{\ln(n)}\right)^{1/r}},
    \end{equation}
    which implies
    \begin{equation}
        (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall n\geq m_\varepsilon)\quad b_n\geq\left(\left(1-\frac{\varepsilon}{2}\right)\left(\frac{2\beta}{\ln(n)}\right)\right)^{1/r}.\label{260106}
    \end{equation}
    This combined with \cref{p:R3sequence1} yields
    $ (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall\gamma\in\left]0,2-\varepsilon\right])$
    \begin{subequations}
        \begin{align}
           \quad\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma&\geq\sum_{n=m_\varepsilon}^{\infty}\norm{x^{(2n)}-x^{(2n-1)}}^\gamma
           \notag\\
            &=\sum_{n=m_\varepsilon}^{\infty}
            a_n^\gamma\exp\left(-\gamma\beta b_n^{-r}\right)
            \tag{by \cref{p:R3sequence1iii} }\\
            &\geq\sum_{n=m_\varepsilon}^{\infty}
            a_0^\gamma\exp\left(-\gamma\frac{\ln(n)}{2-\varepsilon}\right)
            \tag{by \cref{p:R3sequence1iv} and \cref{260106} }\\
         &=a_0^\gamma\sum_{n=m_\varepsilon}^{\infty}n^{-\frac{\gamma}{2-\varepsilon}}=+\infty;\notag
        \end{align}
    \end{subequations}
consequently, 
    \begin{equation}\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma=+\infty \quad\text{for all $\gamma\in\left]0,2\right[$.}
    \end{equation}
\end{example}

ref_dict.s:last:
\begin{remark}
    In \cite[Example 4.10]{HM2016}, the authors also study the asymptotic behavior of $u_n$ in \cref{e:notcone} with $\beta=1$ and $r=2$. They showed that $\frac{1}{u_n}= O\left(n^{1/t}\right)$ for all $t\in\mathbb{R}_{++}$. Using \cref{p:R2sequence2}, we obtain $\frac{1}{u_n}\sim \sqrt{\frac{\ln(n)}{2}}$, which is a sharper result.
\end{remark}

\section{Conification and limiting examples for nonpolyhedral cones in $\mathbb{R}^3$}

\label{s:last}

In this section, we will construct a family of collections, each containing one polyhedral cone and one non-polyhedral cone, such that \cref{t:GTpolyconeinfi} fails. The construction is based on the conification of \cref{e:notcone}.
 Because the counterexample is in $\RR^3$, we note that it is optimal in the sense that such an example
 cannot be found in $\RR$ or $\RR^2$, where all cones 
 are automatically polyhedral. 

Let $C$ be a closed convex subset of $X$ such that $0\in C$. Recall that the \emph{conification} (also known as \emph{homogenization}) of $C$ is the cone
\begin{equation}
    K:=\ccone(C\times\{1\}) \subseteq X\times\RR.
\end{equation}
We consider the case where our collection consists of
\begin{equation}
    H:=\mathbb{R}\times\{0\}\times\mathbb{R}\quad\text{and}\quad 
    K:=\ccone(\epi f\times\{1\}) \subseteq \RR\times\RP\times\RP,
\end{equation}
where $f:\mathbb{R}\to\left]-\infty,+\infty\right]$ is
\begin{equation}
    \text{convex, differentiable on $[0,\delta]$, $\delta\in\mathbb{R}_{++}$, lower semicontinuous, and proper,}
\end{equation}
with
\begin{equation}
    f\text{ even, }f(0)=0,f>0\text{ otherwise, and }f'(0)=0.
\end{equation}

The projection onto $H$ is simple:
\begin{equation}
    P_H\colon \RR^3\to\RR^3 \colon (x_1,x_2,x_3)\mapsto(x_1,0,x_3).\label{251215a}
\end{equation}
The following fact gives a formula for the projection onto $K$ in terms of $C$ and its recession cone\footnote{The \emph{recession cone} of $C$ is defined by $\rec(C)=\{x\in X\mid x+C\subseteq C\}$.} (see \cite[Theorem~4.1 and 5.1]{BTH2023}):
\begin{fact}\label{f:hcone}
    For all $(y,s)\in X\times\RR$, the function
    \begin{align}
        \Psi_{(y,s)}:\RR\to\RR:\alpha\mapsto\begin{cases}
            +\infty,&\text{ if }\alpha<0;\\
            d^2_{\rec C}\left(y\right)+s^2,&\text{ if }\alpha=0;\\
            \alpha^2 d_{C}^2(y/\alpha)+(\alpha-s)^2,&\text{ if }\alpha>0,
        \end{cases}
    \end{align}
    is strictly convex and supercoercive\footnote{
Recall that a function $f\colon X\to[-\infty,+\infty]$ is \emph{supercoercive} if 
    $\lim_{\norm{x}\to+\infty}\frac{f(x)}{\norm{x}}=+\infty$. 
}, with unique minimizer $\alpha^*\geq0$. Moreover, we have
    \begin{equation}
        (\forall\alpha>0)\quad\Psi_{(y,s)}'(\alpha)=-2\alpha\langle P_C(y/\alpha),(\Id-P_C)(y/\alpha)\rangle+2(\alpha-s).
    \end{equation}
    The projection onto $K$ is then given by
    \begin{align}
        P_K(y,s)=\begin{cases}
            \left(P_{\rec (C)}(y),0\right),&\text{ if }\alpha^*=0;\\
            \left(\alpha^*P_C(y/\alpha^*),\alpha^*\right),&\text{ if }\alpha^*>0.
        \end{cases}
    \end{align}
\end{fact}

For the analysis later on, we will need the following fact (see \cite[Proposition~9.29 and Example~9.32]{BC2017}):
\begin{fact}\label{f:supercoercive}
    Let $f\colon X\to\left]-\infty,+\infty\right]$ be convex, lower semicontinuous, and proper. If $f$ is supercoercive, then 
    $\rec\epi f=\epi\iota_{\{0\}} = \{0\}\times\RP\subseteq X\times\RR$, 
    where $\iota$ is the indicator function.
\end{fact}

Let $b_0\in\left]0,1\right[$ and 
$a_0>0$ such that $x^{(0)}=a_0(b_0,0,1)\in\left]0,\delta\right[\times\{0\}\times\mathbb{R}_{++}\subseteq H$. Generate the sequence of alternating projections via
\begin{equation}
    x^{(2n+1)} := P_{K}x^{(2n)}\text{ and }x^{(2n+2)} := P_{H}x^{(2n+1)}.\label{251215b}
\end{equation}
