\begin{proposition}\label{p:R3sequence1}
    Suppose that $f$ is supercoercive. Then
    \begin{enumerate}[ref=\currentenv~\theproposition(\roman*)]
        {
        \item\label{p:R3sequence1i-}
        $H \cap K = \{0\}\times\{0\}\times\RP$.        }
        \item\label{p:R3sequence1i} $x^{(n)} \to \bar{x} := \bar{a}(0,0,1) \in 
        (H \cap K)\smallsetminus\{0\}$.
        \item\label{p:R3sequence1ii} For all $n\in\mathbb{N}$: $0\notin\argmin\Psi_{x^{(2n)}}$.
        \item\label{p:R3sequence1iii} For all $n\in\mathbb{N}\smallsetminus\{0\}$, the iterates have the following form
        \begin{equation}
            x^{(2n-1)}=a_n\left(b_n,f(b_n),1\right)\quad\text{and}\quad x^{(2n)}=a_n(b_n,0,1),
        \end{equation}
        where
        \begin{equation}
            \{a_{n}\}=\argmin\Psi_{x^{(2n-2)}}\quad\text{and}\quad \left(b_{n},f(b_n)\right)=P_{\epi f}\Big(\frac{a_{n-1}}{a_{n}}(b_{n-1},0)\Big),
        \end{equation}
        and $a_n,b_n>0$. Moreover, 
        \begin{equation}
            (\forall n\in\mathbb{N}\smallsetminus\{0\})\quad \frac{a_{n-1}}{a_{n}}b_{n-1}=b_{n}+f(b_n)f'(b_n).
        \end{equation}
        \item\label{p:R3sequence1iv} For all $n\in\mathbb{N}\smallsetminus\{0\}$:
        \begin{equation}
            \frac{a_{n-1}}{a_n}=1+f(b_n)\big(f(b_n)-f'(b_n)b_n\big).
        \end{equation}
        Moreover,
        \begin{equation}
            (\forall n\in\mathbb{N})\quad 0<a_{n}\leq a_{n+1}\quad\text{and}\quad 0<b_{n+1}<\frac{a_n}{a_{n+1}}b_n\leq b_n,
        \end{equation}
        and 
        \begin{equation}
        a_n\to\bar{a}>0,\;\; b_n\to 0.
        \end{equation}
    \end{enumerate}
\end{proposition}
\begin{proof}
    {
    {\it (i)}: 
    \cref{f:supercoercive} in tandem with 
    \cite[Corollary~6.53]{BC2017} yield 
    \begin{equation}
    \label{e:251231b}
    K = \ccone(\epi f \times \{0\}) = \menge{\alpha(x,y,1)}{\alpha>0, f(x)\leq y} \cup 
    \big(\{0\}\times\RP\times \{0\}\big).
    \end{equation}
    Let $(u,v,w)\in H\cap K$. Because $(u,v,w)\in H$, we have $v=0$. 
    Suppose first that there exists $\alpha>0$ such that 
    $u=\alpha x, v=\alpha y, w=\alpha$ and $f(x)\leq y$. 
    Now $v=0$, so $y=0$ which yields $f(x)=0$, i.e., $x=0$. 
    Thus $(u,v,w) \in \{0\}\times\{0\}\times\RPP$. 
    Now suppose that $(u,v,w)\in\{0\}\times\RP\times\{0\}$. 
    Then $(u,v,w)=(0,0,0)$. 
    In either case, $(u,v,w)\in\{0\}\times\{0\}\times\RP$ and so
    \begin{equation}
    H\cap K \subseteq \{0\}\times\{0\}\times\RP. 
    \end{equation}
    Conversely, let $(0,0,\beta)\in \{0\}\times\{0\}\times\RP$. 
    Clearly, $(0,0,\beta)\in H$. 
    If $\beta=0$, then $(0,0,\beta)=(0,0,0) \in \{0\}\times \RP \times\{0\} 
    \subseteq K$ by \cref{e:251231b}. 
    And if $\beta>0$, then $(0,0,\beta) = \beta(0,f(0),1) \in K$, again 
    by \cref{e:251231b}. 
    Altogether, $(0,0,\beta)\in H\cap K$ and we've verifed \cref{p:R3sequence1i-}. 
    }

    {\it (ii)}: \cref{p:R3sequence1i-} and
    \cite[Theorem~1]{Bregman1965} imply 
    $x^{(n)} \to \bar{x} = \bar{a}(0,0,1) \in H \cap K=
    \{0\}\times\{0\}\times\RP$. 
    Since $a_0(0,0,1)\in H\cap K$ and $(x^{(n)})_{n\in\NN}$ is Fej\'er monotone with respect to $H\cap K$ we obtain
    \begin{equation}
        (\forall n\in\NN)\quad d_{\{a_0(0,0,1)\}}\big(x^{(n)}\big)\leq d_{\{a_0(0,0,1)\}}\big(x^{(0)}\big)=a_0b_0.
    \end{equation}
    By the continuity of the distance function, we get that
    \begin{equation}
        |\bar{a}-a_0|=d_{\{a_0(0,0,1)\}}\left(\bar{x}\right)\leq a_0b_0.
    \end{equation}
    Since $a_0>0$ and $b_0<1$ by assumption, this implies $\bar{a}>0$.

    {\it (iii)}: Since $f$ is supercoercive, \cref{f:supercoercive} yields 
    $\rec\epi f=\{0\}\times\RP$. 
    By combining this with \cref{251215b} and \cref{f:hcone}, we get that
    \begin{subequations}
        \begin{align}
            (\forall n\in\mathbb{N})\quad x^{(2n+1)}=P_Kx^{(2n)}&=\begin{cases}
            \left(P_{\rec (\epi f)}\left(x^{(2n)}_1,x^{(2n)}_2\right),0\right),&\text{ if }\alpha^*=0;\\
            \left(\alpha^*P_{\epi f}\left(\frac{1}{\alpha^*}\left(x^{(2n)}_1,x^{(2n)}_2\right)\right),\alpha^*\right),&\text{ if }\alpha^*>0,
            \end{cases}\\
            &=\begin{cases}
            \left(0,\max\left\{x^{(2n)}_2,0\right\},0\right),&\text{ if }\alpha^*=0;\\
            \left(\alpha^*P_{\epi f}\left(\frac{1}{\alpha^*}\left(x^{(2n)}_1,x^{(2n)}_2\right)\right),\alpha^*\right),&\text{ if }\alpha^*>0,
            \end{cases}
        \end{align}
    \end{subequations}
    where $\{\alpha^*\}=\amin \Psi_{x^{(2n)}}$. By \cref{251215a}, we have $P_H\big(0,
    \max\{x^{(2n)}_2,0\},0\big)=(0,0,0)$. It then follows from \cref{p:R3sequence1i} that $0\notin \amin \Psi_{x^{(2n)}}$ for all $n\in\mathbb{N}$.

    {\it(iv)}: We will prove this by induction. For the base case $n=1$, by \eqref{251215b}, \cref{p:R3sequence1ii}, and \cref{f:hcone}, we have
    \begin{equation}
        x^{(1)}=P_{K}x^{(0)}=a_1\bigg(P_{\epi f}\Big(\frac{a_0}{a_{1}}(b_0,0)\Big),1\bigg)=a_1\big(b_1,f(b_1),1\big),
    \end{equation}
    where
    \begin{equation}
        \RR_{++}\supset\{a_{1}\}=\argmin\Psi_{x^{(0)}}\quad\text{and}\quad \big(b_{1},f(b_1)\big)=P_{\epi f}\Big(\frac{a_0}{a_{1}}(b_0,0)\Big).
    \end{equation}
    Since $a_0,b_0\in\mathbb{R}_{++}$ by assumption, \cref{f:epi} yields $b_1\in\bigl]0,\frac{a_0}{a_1}b_0\bigr[\subset \mathbb{R}_{++}$. Using \cref{251215a} and \cref{251215b}, we obtain $x^{(2)}=P_Hx^{(1)}=a_1(b_1,0,1)$.

    Now assume that for some $k\in\mathbb{N}\smallsetminus\{0\}$, we have
    \begin{equation}
        x^{(2k-1)}=a_k\big(b_k,f(b_k),1\big)\quad\text{and}\quad x^{(2k)}=a_k(b_k,0,1),
    \end{equation}
    where $a_k,b_k>0$. By \cref{251215b}, \cref{p:R3sequence1ii} 
    and \cref{f:hcone}, we have
    \begin{equation}
        x^{(2k+1)}=P_{K}x^{(2k)}=a_{k+1}\left(P_{\epi f}\Big(\frac{a_k}{a_{k+1}}(b_k,0)\Big),1\right)
        =a_{k+1}\big(b_{k+1},f(b_{k+1}),1\big),
    \end{equation}
    where
    \begin{equation}
        \RR_{++}\supset\{a_{k+1}\}=\argmin\Psi_{x^{(2k)}}\quad\text{and}\quad \big(b_{k+1},f(b_{k+1})\big)=P_{\epi f}\Big(\frac{a_k}{a_{k+1}}(b_k,0)\Big).
    \end{equation}
    Since $a_k,b_k>0$ by assumption, \cref{f:epi} yields $b_{k+1}\in\bigl]0,\frac{a_k}{a_{k+1}}b_k\bigr[\subset \mathbb{R}_{++}$. Using \cref{251215a} and \cref{251215b}, we obtain $x^{(2k+2)}=P_Hx^{(2k+1)}=a_{k+1}(b_{k+1},0,1)$. The ``Moreover'' part follows from \cref{f:epi}.

    {\it(v)}: By \cref{p:R3sequence1iii} and \cref{f:hcone}, we get that $0<a_n\in\argmin\Psi_{(a_{n-1}b_{n-1},0,a_{n-1})}$ for all $n\in\mathbb{N}\setminus\{0\}$ and $\Psi_x$ is convex for all $x\in \mathbb{R^3}$. This implies that for all $n\in\NN\smallsetminus\{0\}$
\begin{subequations}
\begin{align}
0
=
\qquad\ \:&\Psi'_{(a_{n-1}b_{n-1},0,a_{n-1})}(a_n)
\\   
\eqoverset{\text{\cref{f:hcone}}}{=}
\quad\ \ \ &-2a_n\left\langle P_{\epi f}
\Big(\frac{a_{n-1}b_{n-1}}{a_n},0\Big),(\Id-P_{\epi f})\Big(\frac{a_{n-1}b_{n-1}}{a_n},0\Big)\right\rangle +2(a_n-a_{n-1})\\
\eqoverset{\text{\cref{p:R3sequence1iii}}}{=}
\,&-2a_n\left\langle \big(b_n,f(b_n)\big),\Big(\frac{a_{n-1}b_{n-1}}{a_n},0\Big)-\big(b_n,f(b_n)\big)\right\rangle
+2(a_n-a_{n-1})\\
\eqoverset{\text{\cref{p:R3sequence1iii}}}{=}
\,&-2a_n\left\langle \big(b_n,f(b_n)\big),\left(f(b_n)f'(b_n),-f(b_n)\right)\right\rangle+2(a_n-a_{n-1})\\
=
\qquad\ \:&-2a_n\big(b_nf(b_n)f'(b_n)-f^2(b_n)\big)+2(a_n-a_{n-1})
\\
=
\qquad\ \:&-2a_nf(b_n)\big(b_nf'(b_n)-f(b_n)\big)+2(a_n-a_{n-1}).
\end{align}
\end{subequations}
    Switch sides, simplify, and apply the convexity of $f$, we obtain
    \begin{equation}
        0<\frac{a_{n-1}}{a_n}=1+f(b_n)\left(f(b_n)+f'(b_n)(0-b_n)\right)\leq1+f(b_n)f(0)=1.\label{251215c1}
    \end{equation}
    From \cref{p:R3sequence1iii}, we get that $\left(b_{n},f(b_n)\right)=P_{\epi f}\big(\frac{a_{n-1}}{a_{n}}(b_{n-1},0)\big)$, and $b_n>0$ for all $n\in\mathbb{N}\smallsetminus\{0\}$. \cref{f:epi} and \cref{251215c1} then yields $b_{n}\in\bigl]0,\frac{a_{n-1}}{a_{n}}b_{n-1}\bigr[\subseteq\left]0,b_{n-1}\right[$ for all $n\in\mathbb{N}\smallsetminus\{0\}$. 
    The convergence $a_n\to\bar{a}$ and $b_n\to0$ follows from \cref{p:R3sequence1i} and \cref{p:R3sequence1iii}.
\end{proof}

Next, we analyze the asymptotic behavior of $(b_n)_{n\in\mathbb{N}}$.
\begin{proposition}\label{p:R3sequence2}
    Suppose that $f$ is supercoercive and there exists $q\in\mathbb{R}$ and $p,\alpha\in\mathbb{R}_{++}$ such that
    \begin{equation}
        \lim_{x\searrow0}\frac{f(x)f'(x)}{x^q\exp(-\alpha x^{-p})}=c_{q,\alpha,p}>0.\label{251215c}
    \end{equation}
    Then $\displaystyle \frac{b_n}{\left(\frac{\alpha}{\ln(n)}\right)^{1/p}}\to1$ as $n\to\infty$.
\end{proposition}
\begin{proof}
    By \cref{p:R3sequence1iii} and \cref{p:R3sequence1iv}, we obtain $0<a_n\leq a_{n+1}\to\bar{a}$, $b_n\geq\frac{a_n}{a_{n+1}}b_n>b_{n+1}\to0^+$, and
    \begin{equation}
        (\forall n\in\mathbb{N}\smallsetminus\{0\})\quad \frac{a_{n-1}}{a_n}b_{n-1}=b_n+f(b_n)f'(b_n).\label{251215e}
    \end{equation}
    This yields
    \begin{equation}
        (\forall n\in\mathbb{N}\smallsetminus\{0\})\quad \frac{f(b_n)f'(b_n)}{b_n^q\exp(-\alpha b_n^{-p})}=\frac{\frac{a_{n-1}}{a_n}b_{n-1}-b_n}{b_n^q\exp(-\alpha b_n^{-p})}.\label{251215f}
    \end{equation}
    By checking the derivative, 
    $\displaystyle \frac{1}{x^q\exp(-\alpha x^{-p})}$ is decreasing on $\mathbb{R}_{++}$ if $q\geq0$ and on $\Bigl]0,\big(\frac{-q}{\alpha p}\big)^{-1/p}\Bigr[$ if $q<0$. WLOG, assume that $b_0$ lies inside the decreasing interval. Since $\frac{a_{n-1}}{a_{n}}b_{n-1}>b_{n}$, we get
    \begin{subequations}\label{251215i}
        \begin{align}
            (\forall n\in\mathbb{N}\smallsetminus\{0\})\quad\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{b_n^q\exp(-\alpha b_n^{-p})}&\geq\int_{b_n}^{\frac{a_{n-1}}{a_{n}}b_{n-1}}\frac{dx}{x^q\exp(-\alpha x^{-p})}\\
            &\geq\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^q\exp\Big(-\alpha \big(\frac{a_{n-1}}{a_{n}}b_{n-1}\big)^{-p}\Big)}.
        \end{align}
    \end{subequations}
    It follows from $b_n\searrow0^+$, \cref{251215c}, and \cref{251215f} that
    \begin{equation}
        \lim_{n\to\infty}\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{b_n^q\exp(-\alpha b_n^{-p})}=c_{q,\alpha,p}>0.\label{251215g}
    \end{equation}
    Observe that \cref{251215c} and \cref{251215e} implies
    \begin{subequations}
    \label{251215h}
        \begin{align}
            \lim_{n\to\infty}\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}}{b_n}&=1+\lim_{n\to\infty}\frac{f(b_n)f'(b_n)}{b_n}\\
            &=1+\lim_{n\to\infty}\frac{f(b_n)f'(b_n)}{b_n^q\exp(-\alpha b_n^{-p})}\frac{b_n^q\exp(-\alpha b_n^{-p})}{b_n}\\
       &=1+c_{q,\alpha,p}\lim_{n\to\infty}\frac{b_n^{q-1}}{\exp(\alpha b_n^{-p})}\\
            &=1.
        \end{align}
    \end{subequations}
    By combining \cref{251215g} and \cref{251215h}, we obtain
    \begin{subequations}
        \begin{align}
            &\lim_{n\to\infty}\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^q\exp\left(-\alpha \left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)}\\
            =\ &\lim_{n\to\infty}\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{b_{n}^q\exp(-\alpha b_{n}^{-p})}\frac{b_{n}^q\exp(-\alpha b_{n}^{-p})}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^q\exp\left(-\alpha \left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)}\\
            =\ &c_{q,\alpha,p}\lim_{n\to\infty}\frac{b_n^q}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^q}\exp\left(-\alpha b_n^{-p}\left(1-\frac{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}}{b_n^{-p}}\right)\right)\\
            =\ &c_{q,\alpha,p}\exp\left(-\alpha\lim_{n\to\infty} b_n^{-p}\left(1-\frac{b_{n}^{p}}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{p}}\right)\right).
        \end{align}
    \end{subequations}
    By the Taylor expansion of $1-x^p$ at $x=1$, we get that $\frac{1-x^p}{p(1-x)}\to 1$ as $x\to1$. This together with \cref{251215h} yields
    \begin{equation}
        \frac{1-\frac{b_{n}^{p}}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{p}}}{p\left(1-\frac{b_n}{\frac{a_{n-1}}{a_{n}}b_{n-1}}\right)}\to1.
    \end{equation}
    Hence,
    \begin{subequations}
            \label{251215j}
        \begin{align}
            &\lim_{n\to\infty}\frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_n}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^q\exp\left(-\alpha \left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)}\\
            =\:\,&c_{q,\alpha,p}\exp\left(-\alpha\lim_{n\to\infty} b_n^{-p}\left(1-\frac{b_{n}^{p}}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{p}}\right)\right)\\
            =\:\,&c_{q,\alpha,p}\exp\left(-\alpha p\lim_{n\to\infty} b_n^{-p}\left(1-\frac{b_{n}}{\frac{a_{n-1}}{a_{n}}b_{n-1}}\right)\right)\\
            \eqoverset{\text{\cref{251215h}}}{=}\ 
            &c_{q,\alpha,p}\exp\left(-\alpha p\lim_{n\to\infty} \frac{\frac{a_{n-1}}{a_{n}}b_{n-1}-b_{n}}{b_{n}^{p+1}}\right)\\
            \eqoverset{\text{\cref{251215g}}}{=}
            \ &c_{q,\alpha,p}\exp\left(-\alpha pc_{q,\alpha,p}\lim_{n\to\infty} \frac{b_n^q\exp(-\alpha b_n^{-p})}{b_{n}^{p+1}}\right)\\
            =\:\,&c_{q,\alpha,p}\exp\left(0\right)=c_{q,\alpha,p}.
        \end{align}
    \end{subequations}
    From \cref{251215i}, \cref{251215g}, and \cref{251215j}, we obtain
    \begin{equation}
        \lim_{n\to\infty}\int_{b_n}^{\frac{a_{n-1}}{a_{n}}b_{n-1}}\frac{dx}{x^q\exp(-\alpha x^{-p})}=c_{q,\alpha,p}.\label{251215o}
    \end{equation}
    Since $\displaystyle \frac{1}{x^q\exp(-\alpha x^{-p})}$ is decreasing on 
    $\big[\frac{a_{n-1}}{a_{n}}b_{n-1},b_{n-1}\big]$, we get that
    \begin{subequations}\label{251215k}
        \begin{align}
            0&\leq\int_{\frac{a_{n-1}}{a_{n}}b_{n-1}}^{b_{n-1}}\frac{dx}{x^q\exp(-\alpha x^{-p})}\\
            &\leq\left(b_{n-1}-\frac{a_{n-1}}{a_{n}}b_{n-1}\right)\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-q}\exp\left(\alpha\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)\\
            &= b_{n-1}f(b_n)\left(f'(b_n)b_n-f(b_n)\right)\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-q}
            \exp\left(\alpha\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right), 
        \end{align}
    \end{subequations}
    where we used \cref{p:R3sequence1iv} 
    in the last equality. 
    By \cref{p:R3sequence1iv}, we have $\frac{a_{n-1}}{a_n}\to\frac{\bar{a}}{\bar{a}}=1$. This combined with \cref{251215h} yields
    \begin{equation}
        \frac{b_{n-1}}{b_n}\to1.\label{251215l}
    \end{equation}
    We also get from \cref{251215j} that
\begin{subequations}
\label{251215m}
    \begin{align}
\lim_{n\to\infty}\frac{\exp\left(\alpha\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)}{\exp\left(\alpha b_n^{-p}\right)}
&=\exp\left(-\alpha\lim_{n\to\infty}b_n^{-p}\left(1-\frac{b_n^p}{\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{p}}\right)\right)\\
&=\exp(0)=1.
    \end{align}
\end{subequations}
    By combining \cref{251215l}, \cref{251215h}, and \cref{251215m}, we obtain
    \begin{subequations}
        \begin{align}
            &\lim_{n\to\infty}b_{n-1}f(b_n)\left(f'(b_n)b_n-f(b_n)\right)\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-q}\exp\left(\alpha\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)\\
            =\ &\lim_{n\to\infty}b_{n}f(b_n)\left(f'(b_n)b_n-f(b_n)\right)b_n^{-q}\exp\left(\alpha b_n^{-p}\right)\\
            =\ &\lim_{n\to\infty}b_n^2\left(\frac{f(b_n)f'(b_n)}{b_n^{q}\exp\left(-\alpha b_n^{-p}\right)}-\frac{f^2(b_n)}{b_n^{q+1}\exp\left(-\alpha b_n^{-p}\right)}\right).
        \end{align}
    \end{subequations}
    Since $b_n\searrow 0^+$, by assumption, we obtain $\frac{f(b_n)f'(b_n)}{b_n^{q}\exp\left(-\alpha b_n^{-p}\right)}\to c_{q,\alpha,p}>0$. Moreover, by L'Hôpital's rule, we also get
    \begin{subequations}
        \begin{align}
            \lim_{n\to\infty} \frac{f^2(b_n)}{b_n^{q+1}\exp\left(-\alpha b_n^{-p}\right)}&=\lim_{n\to\infty} \frac{2f(b_n)f'(b_n)}{(q+1)b_n^{q}\exp\left(-\alpha b_n^{-p}\right)+\alpha pb_n^{q-p}\exp\left(-\alpha b_n^{-p}\right)}\\
            &=\lim_{n\to\infty} \frac{2f(b_n)f'(b_n)}{b_n^{q}\exp\left(-\alpha b_n^{-p}\right)\left(q+1+\alpha pb_n^{-p}\right)}\\
            &=0.
        \end{align}
    \end{subequations}
    Altogether, we have
    \begin{equation}
        \lim_{n\to\infty}b_{n-1}f(b_n)\left(f'(b_n)b_n-f(b_n)\right)\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-q}\exp\left(\alpha\left(\frac{a_{n-1}}{a_{n}}b_{n-1}\right)^{-p}\right)=0.\label{251215n}
    \end{equation}
    It then follows from \cref{251215k} and \cref{251215n} that
    \begin{equation}
        \lim_{n\to\infty}\int_{\frac{a_{n-1}}{a_{n}}b_{n-1}}^{b_{n-1}}\frac{dx}{x^q\exp(-\alpha x^{-p})}=0.
    \end{equation}
    This combined with \cref{251215o} yields
    \begin{equation}
        \lim_{n\to\infty}\int_{b_n}^{b_{n-1}}\frac{dx}{x^q\exp(-\alpha x^{-p})}=c_{q,\alpha,p}.
    \end{equation}
    The remainder of the proof is identical to the corresponding part of the proof of \cref{p:R2sequence2}, starting at \cref{260101a}. 
\end{proof}

\begin{example}[G\"unt\"urk-Thao fails for a plane 
and a non-polyhedral cone in $\RR^3$]
\label{e:cone}
    Let $\beta\in \mathbb{R}_{++}$ and $r\in\{2,4,6,\ldots\}$. 
    Consider the function $f(x)=\exp(-\beta x^{-r})$ with domain $\bigl[-\left(\beta r/(r+1)\right)^{1/r},\left(\beta r/(r+1)\right)^{1/r}\bigr]$. Note that $f$ is supercoercive and hence, the assumption of \cref{p:R3sequence2} is satisfied with $q=-r-1$, $\alpha=2\beta$, $p=r$, and $c_{q,\alpha,p}=r\beta$. Hence, we obtain
    \begin{equation}
        1=\lim_{n\to\infty}\frac{b_n}{\left(\frac{\alpha}{\ln(n)}\right)^{1/p}}=\lim_{n\to\infty}\frac{b_n}{\left(\frac{2\beta}{\ln(n)}\right)^{1/r}},
    \end{equation}
    which implies
    \begin{equation}
        (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall n\geq m_\varepsilon)\quad b_n\geq\left(\left(1-\frac{\varepsilon}{2}\right)\left(\frac{2\beta}{\ln(n)}\right)\right)^{1/r}.\label{260106}
    \end{equation}
    This combined with \cref{p:R3sequence1} yields
    $ (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall\gamma\in\left]0,2-\varepsilon\right])$
    \begin{subequations}
        \begin{align}
           \quad\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma&\geq\sum_{n=m_\varepsilon}^{\infty}\norm{x^{(2n)}-x^{(2n-1)}}^\gamma
           \notag\\
            &=\sum_{n=m_\varepsilon}^{\infty}
            a_n^\gamma\exp\left(-\gamma\beta b_n^{-r}\right)
            \tag{by \cref{p:R3sequence1iii} }\\
            &\geq\sum_{n=m_\varepsilon}^{\infty}
            a_0^\gamma\exp\left(-\gamma\frac{\ln(n)}{2-\varepsilon}\right)
            \tag{by \cref{p:R3sequence1iv} and \cref{260106} }\\
         &=a_0^\gamma\sum_{n=m_\varepsilon}^{\infty}n^{-\frac{\gamma}{2-\varepsilon}}=+\infty;\notag
        \end{align}
    \end{subequations}
consequently, 
    \begin{equation}\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma=+\infty \quad\text{for all $\gamma\in\left]0,2\right[$.}
    \end{equation}
\end{example}

\begin{remark}
    In this specific instance of the alternating projections sequence, it follows from \cref{p:R2sequence2} and \cref{p:R3sequence2} that the iterates $(u_n)_{n\in\mathbb{N}}$ and their conified counterparts $(b_n)_{n\in\mathbb{N}}$ have the same asymptotic behavior. One can also obtain a conified version of \cite[Proposition 4.5]{HM2016} by the same procedure used to conify \cref{p:R2sequence2} into \cref{p:R3sequence2}. The argument is simpler and largely repetitive, so we leave the details to the interested reader.
\end{remark}

