+ \|u\|_{L_x^{60/13}L_t^{15}(A)} \\
&~{} \quad + \|u\|_{W_x^{s,10/3}L_t^{30/7}(A)}
+ \|\partial_x u\|_{L_x^{\infty} L_t^2(A)}+ \|D^s_x\partial_x u\|_{L_x^{\infty} L_t^2(A)}; 
\end{aligned} \label{eq:Y4s_norm}\\
 &\|u\|_{Y_{5,s}(A)} := \|u\|_{L_x^5L_t^{10}(A)}. \label{eq:Y5s_norm}
\end{align}
are the norms that we will work in the paper. This norms the equation above arises naturaly from the Kenig-Ponce-Vega theory. In addition we will say that $g \in Y_{k,s}(A)$ if $\|g\|_{Y_{k,s}(A)}<\infty$. Notice that under hypothesis (H1), the norms $\|\cdot\|_{Y_{k,s}}$ can be suitable approximated by a functional $\mathcal Y_{k,s,N,M}$ (cf. Definitions \eqref{eq:Y2s_appr}-\eqref{eq:Y5s_appr}).

\medskip

\noindent
{\bf Hypotheses on PINNs}.
 Let $u_{\text{DNN},\#}= u_{\text{DNN},\#} (t,x)$ be a smooth bounded function constructed by means of an algorithmic procedure (either SGD or any other ML optimization procedure) and realization of a suitable PINNs, in the following sense: under the framework \eqref{Loss1}, one has:
\begin{enumerate}
\item[(H2)] \emph{Uniformly bounded large time $L^\infty_tH^s_x$, initial time $H^s_x$ and large time $Y_{k,s}$ control for $u_0$ and $u_{\text{DNN},\#}$}.  There are $A,\widetilde A,B>0$ such that the following holds. For any $N_{1,0},N_{2,0},N_{3,0}\geq 1$ and $M_{2,0},M_{3,0}\geq 1$, there are $N_j\geq N_{j,0}$ and $M_j\geq M_{j,0}$,  such that each approximate norm satisfies
\[
\begin{aligned}
 \mathcal J_{L^2_x,N_1} [(u_0-u_{\text{DNN},\#}(0))]+\mathcal J_{L^2_x,N_1} [D_x^s(u_0-u_{\text{DNN},\#}(0))] &\leq \widetilde{A}, \\
 \mathcal J_{\infty,2,N_2,M_2} [u_{\text{DNN},\#}] + \mathcal J_{\infty,2,N_2,M_2} [D_x^su_{\text{DNN},\#}] &\leq A, \\ \mathcal Y_{k,s,N_3,M_3} [u_{\text{DNN},\#}]  &\leq L.
\end{aligned}
for regularity $s>s_k$ and nonlinearity power $k$. Finally, this global-in-space functional control “will reduce to the auxiliary bounds
\begin{align}
\|\partial_x(u^k-u^k_{\emph{DNN},\#})\|_{L_x^2L_t^2(I\times[-R,R])} & \leq C(A, \widetilde{A},L)\varepsilon, \label{eq:MT1}\\
 \|u-u_{\emph{DNN},\#}\|_{L_t^{\infty}H_x^s(I\times[-R.R])} & \leq C(A, \widetilde{A},L). \label{eq:MT3}
\end{align}
after a suitable localization,” yielding the stated bounds for $u-u_{\mathrm{DNN},\#}$ (and for $\partial_x(u^k-u_{\mathrm{DNN},\#}^k)$) on $I\times[-R,R]$.,

expanded_theorem:
\label{MT}
Let $k \in \{2,3,4,5\}$ and let $s \geq s_k$ for $k \in\{3,4,5\}$ and $s>s_k$ for $k=2$. Assume now the following 
\begin{enumerate}
\item Let $u_0 \in H^s(\mathbb{R})$, and assume \emph{(H1)}. 
\item Let $A,\widetilde A, L >0$ be fixed numbers, and let $0<\varepsilon<\varepsilon_1$ sufficiently small. 
\item Finally, let $u_{\emph{DNN},\#}$ be a DNN satisfying \emph{(H2)-(H3)}. 
\end{enumerate}
Then there exists a solution $u \in C(I;H^s(\mathbb{R}))\cap Y_{k,s}(I\times\mathbb{R})$ to
\begin{equation}\label{eq:KdV}
	\partial_t u + \partial_{xxx} u = \mu \partial_x (u^k),\qquad (t,x)\in \R\times\R,
\end{equation}
on $I\times\mathbb{R}$ with initial datum $u_0 \in H^s(\mathbb{R})$ such that for all $R>0$ sufficiently large and constants $C$, there is smallness in the $Y_{k,s}$ norm:
\begin{align}
    \|u-u_{\emph{DNN},\#}\|_{Y_{k,s}(I\times[-R,R])}& \leq C(A, \widetilde{A},L)\varepsilon. \label{eq:MT2}
\end{align}
Additionally, one has bounded control of the energy norm:
\begin{align}
\|\partial_x(u^k-u^k_{\emph{DNN},\#})\|_{L_x^2L_t^2(I\times[-R,R])} & \leq C(A, \widetilde{A},L)\varepsilon, \label{eq:MT1}\\
 \|u-u_{\emph{DNN},\#}\|_{L_t^{\infty}H_x^s(I\times[-R.R])} & \leq C(A, \widetilde{A},L). \label{eq:MT3}
\end{align}
